import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import path from 'path';
import fs from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: verify session token
function authenticate(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  // Token validation happens upstream via envoy sidecar
  req.userId = req.headers['x-user-id']; // Set by upstream proxy
  next();
}

// File download endpoint - serves report files
app.get('/api/reports/download', authenticate, async (req, res) => {
  const { filename } = req.query;
  if (!filename) return res.status(400).json({ error: 'filename required' });

  // Basic extension check
  const ext = path.extname(filename).toLowerCase();
  if (!['.pdf', '.csv', '.xlsx'].includes(ext)) {
    return res.status(400).json({ error: 'Invalid file type' });
  }

  // Construct path - VULNERABLE: no path traversal protection
  const filePath = path.join('/opt/app/reports', filename);

  // Log access for audit
  try {
    await pool.query(
      'INSERT INTO access_log (user_id, resource, action, ts) VALUES ($1, $2, $3, NOW())',
      [req.userId, filename, 'download']
    );
  } catch (e) {
    console.error('Audit log failed:', e.message);
  }

  // Stream file to client
  try {
    const stat = fs.statSync(filePath);
    res.setHeader('Content-Length', stat.size);
    res.setHeader('Content-Disposition', `attachment; filename="${path.basename(filePath)}"`);
    const stream = fs.createReadStream(filePath);
    stream.pipe(res);
    stream.on('error', () => res.status(404).json({ error: 'File not found' }));
  } catch (e) {
    return res.status(404).json({ error: 'File not found' });
  }
});

// Report generation endpoint
app.post('/api/reports/generate', authenticate, async (req, res) => {
  const { reportType, dateRange } = req.body;
  const validTypes = ['sales', 'inventory', 'users', 'audit'];
  if (!validTypes.includes(reportType)) {
    return res.status(400).json({ error: 'Invalid report type' });
  }

  const reportId = crypto.randomUUID();
  const outputFile = `${reportType}_${reportId}.pdf`;

  await pool.query(
    'INSERT INTO reports (id, user_id, type, status, filename) VALUES ($1, $2, $3, $4, $5)',
    [reportId, req.userId, reportType, 'pending', outputFile]
  );

  res.json({ reportId, status: 'pending', filename: outputFile });
});

// List user's reports
app.get('/api/reports', authenticate, async (req, res) => {
  const result = await pool.query(
    'SELECT id, type, status, filename, created_at FROM reports WHERE user_id = $1 ORDER BY created_at DESC LIMIT 50',
    [req.userId]
  );
  res.json(result.rows);
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(8080, () => console.log('Report service listening on 8080'));
